Add-Type -TypeDefinition 'using System;using System.Text;using System.Runtime.InteropServices;public static class FrankingRefreshNative{[DllImport("user32.dll")]public static extern IntPtr GetMenu(IntPtr h);[DllImport("user32.dll")]public static extern int GetMenuItemCount(IntPtr h);[DllImport("user32.dll",CharSet=CharSet.Unicode)]public static extern int GetMenuString(IntPtr h,uint i,StringBuilder s,int n,uint f);[DllImport("user32.dll")]public static extern IntPtr GetSubMenu(IntPtr h,int i);[DllImport("user32.dll")]public static extern uint GetMenuItemID(IntPtr h,int i);[DllImport("user32.dll")]public static extern uint GetMenuState(IntPtr h,uint i,uint f);[DllImport("user32.dll")]public static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);}'
$editorInfo=Get-Content -LiteralPath Library/EditorInstance.json | ConvertFrom-Json
$editorWindow=(Get-Process -Id $editorInfo.process_id).MainWindowHandle
if($editorWindow -eq [IntPtr]::Zero){throw 'Main editor window unavailable'}
$script:playMenu=$null;$script:refreshMenu=$null
function Inspect-Menu([IntPtr]$menu){for($i=0;$i -lt [FrankingRefreshNative]::GetMenuItemCount($menu);$i++){$label=[Text.StringBuilder]::new(256);[void][FrankingRefreshNative]::GetMenuString($menu,[uint32]$i,$label,256,0x400);if($label.ToString() -match '^&?Play(?:\t|$)'){$script:playMenu=@{Id=[FrankingRefreshNative]::GetMenuItemID($menu,$i);Checked=([FrankingRefreshNative]::GetMenuState($menu,[uint32]$i,0x400) -band 8) -ne 0}};if($label.ToString() -match '^&?Refresh(?:\t|$)'){$script:refreshMenu=[FrankingRefreshNative]::GetMenuItemID($menu,$i)};$sub=[FrankingRefreshNative]::GetSubMenu($menu,$i);if($sub -ne [IntPtr]::Zero){Inspect-Menu $sub}}}
Inspect-Menu ([FrankingRefreshNative]::GetMenu($editorWindow))
if($script:playMenu -and $script:playMenu.Checked){[void][FrankingRefreshNative]::PostMessage($editorWindow,0x111,[IntPtr]$script:playMenu.Id,[IntPtr]::Zero);Write-Output 'Requested Stop Play; repeat only after transition to Edit.'}
elseif($null -ne $script:refreshMenu){[void][FrankingRefreshNative]::PostMessage($editorWindow,0x111,[IntPtr]$script:refreshMenu,[IntPtr]::Zero);Write-Output 'Requested Assets/Refresh in existing main editor.'}
else{throw 'Refresh menu unavailable'}
